```ts
import { parse } from "@ende/jsonc";
import { assertEquals } from "@ende/assert";

assertEquals(parse('{"foo": "bar"}'), { foo: "bar" });
assertEquals(parse('{"foo": "bar", }'), { foo: "bar" });
assertEquals(parse('{"foo": "bar", } /* comment *\/'), { foo: "bar" });
```

